from dataclasses import dataclass
from pathlib import Path
from src.db import get_connection
@dataclass(frozen=True,slots=True)
class PublishingIssue:issue_type:str;severity:str;case_id:str|None;publication_id:str|None;subscriber_id:str|None;delivery_id:str|None;explanation:str
def check_publishing_consistency(path:Path):
 c=get_connection(path);out=[]
 def add(t,row,msg):out.append(PublishingIssue(t,'error',row['case_id'] if 'case_id' in row.keys() else None,row['publication_id'] if 'publication_id' in row.keys() else None,row['subscriber_id'] if 'subscriber_id' in row.keys() else None,row['delivery_id'] if 'delivery_id' in row.keys() else None,msg))
 try:
  checks=[('approved_case_no_publication',"SELECT case_id,NULL publication_id,NULL subscriber_id,NULL delivery_id FROM cases WHERE approval_status='approved' AND NOT EXISTS(SELECT 1 FROM publications p WHERE p.case_id=cases.case_id AND p.publishing_status='published')"),('publication_missing_case',"SELECT p.case_id,p.publication_id,NULL subscriber_id,NULL delivery_id FROM publications p LEFT JOIN cases c ON c.case_id=p.case_id WHERE c.case_id IS NULL"),('publication_missing_package',"SELECT p.case_id,p.publication_id,NULL subscriber_id,NULL delivery_id FROM publications p LEFT JOIN content_packages cp ON cp.content_package_id=p.content_package_id WHERE cp.content_package_id IS NULL"),('published_missing_document',"SELECT case_id,publication_id,NULL subscriber_id,NULL delivery_id FROM publications WHERE publishing_status='published' AND (google_document_id IS NULL OR google_document_url NOT LIKE 'https://%')"),('multiple_current_publications',"SELECT case_id,MAX(publication_id) publication_id,NULL subscriber_id,NULL delivery_id FROM publications WHERE publishing_status='published' GROUP BY case_id HAVING COUNT(*)>1"),('active_unconsented_subscriber',"SELECT NULL case_id,NULL publication_id,subscriber_id,NULL delivery_id FROM subscribers WHERE status='active' AND consent_status!='confirmed'"),('ineligible_subscriber_queued',"SELECT NULL case_id,d.publication_id,d.subscriber_id,d.delivery_id FROM deliveries d JOIN subscribers s ON s.subscriber_id=d.subscriber_id WHERE d.status IN ('queued','sending') AND s.status IN ('unsubscribed','bounced','complained','suppressed')"),('sent_without_provider_id',"SELECT NULL case_id,publication_id,subscriber_id,delivery_id FROM deliveries WHERE status='sent' AND provider_message_id IS NULL"),('delivery_missing_subscriber',"SELECT NULL case_id,d.publication_id,d.subscriber_id,d.delivery_id FROM deliveries d LEFT JOIN subscribers s ON s.subscriber_id=d.subscriber_id WHERE d.subscriber_id IS NOT NULL AND s.subscriber_id IS NULL"),('delivery_missing_publication',"SELECT NULL case_id,d.publication_id,d.subscriber_id,d.delivery_id FROM deliveries d LEFT JOIN publications p ON p.publication_id=d.publication_id WHERE p.publication_id IS NULL"),('emailed_without_success',"SELECT c.case_id,p.publication_id,NULL subscriber_id,NULL delivery_id FROM cases c JOIN publications p ON p.case_id=c.case_id WHERE c.workflow_status='emailed' AND NOT EXISTS(SELECT 1 FROM deliveries d WHERE d.publication_id=p.publication_id AND d.delivery_type='subscriber' AND d.status='sent')"),('terminal_with_queued',"SELECT NULL case_id,p.publication_id,NULL subscriber_id,NULL delivery_id FROM publications p WHERE p.distribution_status IN ('completed','completed_with_failures','failed') AND EXISTS(SELECT 1 FROM deliveries d WHERE d.publication_id=p.publication_id AND d.status IN ('queued','sending'))"),('external_reconciliation_required',"SELECT NULL case_id,publication_id,NULL subscriber_id,delivery_id FROM external_operations WHERE state IN ('external_document_created','compensation_required','provider_accepted')")]
  for kind,sql in checks:
   for r in c.execute(sql):add(kind,r,kind.replace('_',' '))
  for r in c.execute("SELECT NULL case_id,NULL publication_id,subscriber_id,NULL delivery_id FROM subscribers WHERE unsubscribe_token_hash LIKE '%=%' OR LENGTH(unsubscribe_token_hash)<64"):
   add('raw_or_invalid_unsubscribe_token',r,'Unsubscribe token storage is not a SHA-256 hash')
  return out
 finally:c.close()
def reconcile_external_operations(path:Path):return [i for i in check_publishing_consistency(path) if i.issue_type in {'external_reconciliation_required','published_missing_document','sent_without_provider_id'}]
